import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull

class CardioFormatTest {
    private val run = CardioActivity.OUTDOOR_RUN
    private val km = DistanceUnit.KM
    private val mi = DistanceUnit.MI

    @Test
    fun distancePaceAndSpeedFollowTheWorkoutsUnit() {
        assertEquals("5.02 km", CardioFormat.distance(CardioDistance(5.02, km), run, km))
        assertEquals("6:37 /km", CardioFormat.pace(397, run, km))
        assertEquals("12.5 km/h", CardioFormat.speed(12.5, km))
        assertEquals("24 m", CardioFormat.elevation(24, km))
    }

    @Test
    fun imperialReadsMilesPerMileMphAndFeet() {
        assertEquals("3.10 mi", CardioFormat.distance(CardioDistance(3.1, mi), run, mi))
        assertEquals("8:00 /mi", CardioFormat.pace(480, run, mi))
        assertEquals("7.5 mph", CardioFormat.speed(7.5, mi))
        assertEquals("80 ft", CardioFormat.elevation(80, mi))
        assertEquals("0.50 mi", CardioFormat.distance(CardioDistance(800.0, DistanceUnit.M), run, mi))
    }

    @Test
    fun theRowerIsAlwaysMetresPer500m() {
        listOf(km, mi).forEach { unit ->
            assertEquals("2000 m", CardioFormat.distance(CardioDistance(2000.0, DistanceUnit.M), CardioActivity.ROWER, unit))
            assertEquals("1:55 /500 m", CardioFormat.pace(115, CardioActivity.ROWER, unit))
            assertEquals(120, CardioFormat.derivedPace(480, CardioDistance(2000.0, DistanceUnit.M), null, CardioActivity.ROWER, unit))
        }
    }

    @Test
    fun derivedPaceAndSpeedShowOnlyWhenBlankAndBothKnown() {
        val l2 = CardioDistance(5.02, km)

